<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router'
import { ArrowUpRight,Building2,CalendarDays,UsersRound } from 'lucide-vue-next'
import { api,ApiError,errorText } from '../api'
import { useAuth } from '../stores/auth'
import { date,listItems } from '../domain'
import type { Row } from '../domain'
import PageState from '../components/PageState.vue'

const auth=useAuth(),route=useRoute(),router=useRouter()
const items=ref<Row[]>([]),detail=ref<Row|null>(null),departments=ref<Row[]>([]),error=ref(''),busy=ref(false),loading=ref(false),dirty=ref(false),rows=ref<Row[]>([]),totp=ref(''),verifyNeeded=ref(false)
const statusFilter=ref(''),keyword=ref(''),appliedKeyword=ref(''),entryView=ref<'cards'|'table'>('cards'),submittedView=ref<'cards'|'table'>('table'),openResponses=ref<string[]>([])
const defaultFields=[{id:'content',name:'工作内容'},{id:'progress',name:'推进情况'},{id:'problem',name:'存在问题'},{id:'suggestion',name:'解决建议'},{id:'coordination',name:'需要领导协调解决工作'},{id:'timeRequirement',name:'时间要求'},{id:'remark',name:'备注'}]
const statusTabs=[{value:'',name:'全部填表'},{value:'ACTIVE',name:'收集中'},{value:'COMPLETED',name:'已完成'}]
const form=ref<Row>({title:'各部门重点工作及需领导协调解决问题收集',companyId:auth.me?.companyId,deadline:'',departmentIds:[],columns:structuredClone(defaultFields)})
const newColumnName=ref('')
const fields=computed<Row[]>(()=>detail.value?.columns?.length?detail.value.columns:defaultFields)
const creating=computed(()=>route.query.new==='1'),id=computed(()=>route.params.id)
const canCreate=computed(()=>(auth.me?.role==='ADMIN'&&auth.me.companyId==null||['GROUP_LEADER','DIVISION_LEADER','COMPANY_LEADER'].includes(auth.me?.role||''))&&(!auth.me?.permissions||auth.me.permissions.includes('TASK_CREATE')))
const companies=computed(()=>Array.from(new Map(departments.value.map(d=>[String(d.companyId),{id:d.companyId,name:d.companyName||'公司名称不可用'}])).values()))
const companyName=(item:Row)=>companies.value.find(c=>String(c.id)===String(item.companyId))?.name||item.companyName||`公司 ${item.companyId}`
const choices=computed(()=>departments.value.filter(d=>String(d.companyId)===String(form.value.companyId)))
const own=computed(()=>detail.value?.responses?.find((r:Row)=>String(r.deptId)===String(auth.me?.deptId)))
const editable=computed(()=>own.value?.canEdit&&(!auth.me?.permissions||auth.me.permissions.includes('TASK_UPDATE')))
const expired=(item:Row)=>item.status==='ACTIVE'&&new Date(item.deadline).getTime()<Date.now()
const label=(item:Row)=>item.status==='ACTIVE'?(expired(item)?'已截止':'收集中'):item.status==='COMPLETED'?'全部完成':item.status==='SUBMITTED'?'已提交':'未提交'
const visibleItems=computed(()=>items.value.filter(item=>(!statusFilter.value||item.status===statusFilter.value)&&(!appliedKeyword.value||[item.title,companyName(item)].some(value=>String(value||'').toLocaleLowerCase().includes(appliedKeyword.value)))))
const counts=computed(()=>({ACTIVE:items.value.filter(i=>i.status==='ACTIVE').length,COMPLETED:items.value.filter(i=>i.status==='COMPLETED').length}))
const leaveCheck=()=>!dirty.value||window.confirm('当前表格修改尚未保存，是否离开？')
onBeforeRouteLeave(leaveCheck);onBeforeRouteUpdate(leaveCheck)
const blank=()=>Object.fromEntries(fields.value.map(f=>[f.id,'']))
function addColumn(){const name=newColumnName.value.trim();if(!name||name.length>40||form.value.columns.length>=18||form.value.columns.some((c:Row)=>c.name.trim().toLocaleLowerCase()===name.toLocaleLowerCase())){error.value='请输入不重复的列名，最多40字、18列';return}form.value.columns.push({id:'custom_'+crypto.randomUUID().replaceAll('-',''),name});newColumnName.value='';error.value=''}
function moveColumn(index:number,by:number){const columns=form.value.columns;const [column]=columns.splice(index,1);columns.splice(index+by,0,column)}
watch(()=>form.value.companyId,()=>{form.value.departmentIds=[]})
function search(){appliedKeyword.value=keyword.value.trim().toLocaleLowerCase()}
function reset(){keyword.value='';statusFilter.value='';search()}
let request=0
async function load(){if(dirty.value&&!window.confirm('当前修改尚未保存，是否重新加载？'))return;const run=++request;loading.value=true;error.value='';try{if(id.value){const d=await api.get<Row>('/collections/'+id.value);if(run!==request)return;if(detail.value?.id!==d.id)openResponses.value=d.responses.filter((r:Row)=>r.status==='SUBMITTED').map((r:Row)=>String(r.id));detail.value=d;const response=d.responses.find((r:Row)=>String(r.deptId)===String(auth.me?.deptId));rows.value=response?.rows?.length?structuredClone(response.rows):[blank()]}else{const d=await api.get<Row[]>('/collections');if(run!==request)return;items.value=d;detail.value=null}dirty.value=false}catch(e){if(run===request)error.value=errorText(e)}finally{if(run===request)loading.value=false}}
async function create(){if(busy.value)return;if(!form.value.title.trim()||!form.value.companyId||!form.value.deadline||!form.value.departmentIds.length){error.value='请填写标题、公司、截止时间并选择接收部门';return}const names=form.value.columns.map((c:Row)=>c.name.trim());if(!names.length||names.some((name:string)=>!name||name.length>40)||new Set(names.map((name:string)=>name.toLocaleLowerCase())).size!==names.length){error.value='请保留至少一列，并检查列名是否重复或为空';return}form.value.columns=form.value.columns.map((c:Row)=>({...c,name:c.name.trim()}));busy.value=true;error.value='';try{const d=await api.post('/collections',form.value);await router.push('/collections/'+d.id)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function save(submit=false){if(busy.value||!editable.value)return;busy.value=true;error.value='';try{const d=await api.post<Row>(`/collections/${id.value}/${submit?'submit':'draft'}`,{version:own.value.version,rows:rows.value});detail.value=d;const response=d.responses.find((r:Row)=>String(r.deptId)===String(auth.me?.deptId));rows.value=response?.rows?.length?structuredClone(response.rows):[blank()];dirty.value=false}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function download(){if(busy.value)return;busy.value=true;error.value='';try{if(verifyNeeded.value){await api.post('/auth/totp/verify',{code:totp.value});totp.value='';verifyNeeded.value=false}await api.download('/collections/'+id.value+'/export','部门填报汇总.xlsx')}catch(e){error.value=errorText(e);verifyNeeded.value=e instanceof ApiError&&e.code==='FRESH_TOTP_REQUIRED'}finally{busy.value=false}}
watch(()=>[route.params.id,route.query.new],()=>{dirty.value=false;void load()})
onMounted(()=>{void load();api.get('/organization/departments').then(d=>departments.value=listItems(d)).catch(e=>error.value=errorText(e))})
</script>

<template>
 <div v-if="id||creating" class="backline"><router-link to="/collections">← 部门填表与汇总</router-link><span>{{ creating?'发起填表':'填表详情' }}</span></div>
 <section v-if="!id" class="page-heading"><div><p class="eyebrow">DEPARTMENT COLLECTION</p><h1>{{ creating?'发起部门填表':'部门填表与汇总' }}</h1><p class="muted">按部门收集工作事项与协调需求，提交后即完成。</p></div><div class="action-strip"><router-link v-if="!creating&&canCreate" to="/collections?new=1"><el-button type="primary">＋ 发起填表</el-button></router-link><el-button v-if="!creating" :loading="loading" @click="load">刷新</el-button></div></section>
 <el-alert v-if="error&&(creating||id)" :title="error" type="error" :closable="false" show-icon/>

 <section v-if="creating&&canCreate" class="panel collection-create"><div class="section-intro"><span class="section-index">01</span><div><h2>填表基本信息</h2><p class="muted">选择接收部门和截止时间，发布后各部门独立填写。</p></div></div><el-form label-position="top" @submit.prevent="create"><el-form-item label="填表标题" required><el-input v-model="form.title" maxlength="300"/></el-form-item><div class="form-pair"><el-form-item label="所属公司" required><el-select v-model="form.companyId"><el-option v-for="c in companies" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-form-item label="截止时间（北京时间）" required><el-date-picker v-model="form.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item></div><el-form-item label="接收部门" required><el-select v-model="form.departmentIds" multiple filterable style="width:100%"><el-option v-for="d in choices" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><div class="column-editor"><div class="row-between"><div><h3>填报列 <small>{{ form.columns.length }} / 18</small></h3><p class="muted">可重命名、删除默认列，也可新增和调整顺序。发布后列方案固定。</p></div></div><div v-for="(column,index) in form.columns" :key="column.id" class="column-row"><span class="column-index">{{ index+1 }}</span><el-input v-model="column.name" maxlength="40" :aria-label="'第'+(index+1)+'列名称'" placeholder="填写列名"/><el-button :disabled="index===0" :aria-label="'上移'+column.name" @click="moveColumn(index,-1)">上移</el-button><el-button :disabled="index===form.columns.length-1" :aria-label="'下移'+column.name" @click="moveColumn(index,1)">下移</el-button><el-button type="danger" plain :aria-label="'删除'+column.name" @click="form.columns.splice(index,1)">删除</el-button></div><div class="column-add"><el-input v-model="newColumnName" maxlength="40" placeholder="输入新列名称" aria-label="新列名称" @keydown.enter.prevent="addColumn"/><el-button :disabled="form.columns.length>=18" @click="addColumn">＋ 新增列</el-button></div></div><p class="scope-note">请保留至少一列。每部门最多100条事项、每格最多2000字，总计最多20000字。提交后即完成，无需审核。</p><div class="form-footer"><router-link to="/collections"><el-button>返回列表</el-button></router-link><el-button type="primary" native-type="submit" :loading="busy">发布填表</el-button></div></el-form></section>

 <section v-else-if="!id" class="collection-list" :aria-busy="loading">
<div class="status-tabs" role="tablist" aria-label="部门填表状态"><button v-for="tab in statusTabs" :key="tab.value" role="tab" :aria-selected="statusFilter===tab.value" :class="{selected:statusFilter===tab.value}" @click="statusFilter=tab.value">{{ tab.name }} <small>{{ tab.value?counts[tab.value as 'ACTIVE'|'COMPLETED']:items.length }}</small></button></div><form class="filter-bar" @submit.prevent="search"><el-input v-model="keyword" clearable placeholder="搜索填表标题 / 公司" aria-label="搜索填表标题或公司"/><el-button type="primary" plain native-type="submit">查询</el-button><el-button @click="reset">重置</el-button></form><div class="list-caption"><span>共 {{ visibleItems.length }} 项填表</span><span>各部门提交后即完成 · 截止时间按北京时间显示</span></div>
 <PageState :loading="loading&&!items.length" :error="error" @retry="load"><div v-if="visibleItems.length" class="collection-grid"><router-link v-for="item in visibleItems" :key="item.id" :to="'/collections/'+item.id" class="collection-card" :class="{'is-overdue':expired(item)}" :aria-label="'查看填表 '+item.title"><div class="card-top"><span class="card-code">部门填表 · #{{ item.id }}</span><span class="collection-status" :class="{completed:item.status==='COMPLETED',expired:expired(item)}"><span class="status-dot"/>{{ label(item) }}</span></div><h2>{{ item.title }}</h2><dl class="card-meta"><div><dt><Building2 :size="14" aria-hidden="true"/>所属公司</dt><dd>{{ companyName(item) }}</dd></div><div><dt><UsersRound :size="14" aria-hidden="true"/>接收部门</dt><dd>{{ item.departmentCount }} 个部门</dd></div><div><dt><CalendarDays :size="14" aria-hidden="true"/>截止时间</dt><dd>{{ date(item.deadline) }}</dd></div></dl><div class="card-update"><b>部门提交情况</b><p>{{ item.submitted }} / {{ item.departmentCount }} 个部门已提交</p><small>{{ item.status==='COMPLETED'?'全部部门已完成':expired(item)?'填报时间已结束':'等待接收部门提交' }}</small></div><footer class="card-footer"><span>{{ item.status==='COMPLETED'?'已完成汇总':'正在收集' }}</span><span class="card-details">查看详情 <ArrowUpRight :size="14" aria-hidden="true"/></span></footer></router-link></div><el-empty v-else :description="items.length?'没有符合条件的填表':'暂无需要填写或查看的表格'"/></PageState>
</section>

 <PageState v-else :loading="loading&&!detail" :error="!detail?error:''" @retry="load">
<template v-if="detail">
<section class="panel collection-hero"><div class="row-between"><p class="eyebrow">部门填表 · #{{ detail.id }}</p><span class="collection-status" :class="{completed:detail.status==='COMPLETED',expired:expired(detail)}"><span class="status-dot"/>{{ label(detail) }}</span></div><h1>{{ detail.title }}</h1><div class="detail-meta"><span>所属公司 <b>{{ companyName(detail) }}</b></span><span>截止 <b>{{ date(detail.deadline) }}</b></span><span>接收部门 <b>{{ detail.departmentCount }} 个</b></span><span>已提交 <b>{{ detail.submitted }} 个</b></span></div><div class="department-overview"><div class="row-between"><h2>部门提交情况</h2><small class="muted">{{ detail.submitted }} / {{ detail.departmentCount }} 个部门完成</small></div><div class="department-list"><div v-for="response in detail.responses" :key="response.id" class="department-line"><b>{{ response.departmentName }}</b><span class="collection-status" :class="{completed:response.status==='SUBMITTED'}"><span class="status-dot"/>{{ response.status==='SUBMITTED'?'已提交':'待提交' }}</span><small v-if="response.submittedAt" class="muted">{{ date(response.submittedAt) }}</small></div></div></div><div v-if="detail.canManage&&(!auth.me?.permissions||auth.me.permissions.includes('REPORTS'))" class="hero-actions"><el-button :loading="busy" @click="download">导出已提交汇总 Excel</el-button><template v-if="verifyNeeded"><el-input v-model="totp" maxlength="6" inputmode="numeric" placeholder="六位动态验证码" style="max-width:180px"/><el-button @click="download">验证并导出</el-button></template></div></section>

 <section v-if="own" class="panel response-panel">
<div class="row-between"><div><h2>{{ own.departmentName }} · 本部门填报</h2><p class="muted">{{ rows.length }} 条工作事项 · {{ own.status==='SUBMITTED'?'已提交':'共享草稿' }}</p></div><span v-if="dirty" class="unsaved">有未保存修改</span></div><p v-if="!editable" class="notice">{{ own.status==='SUBMITTED'?'本部门已提交，内容已锁定。':'当前已截止或当前岗位仅可查看。' }}</p><div class="view-switch" role="group" aria-label="填表展示方式"><button :aria-pressed="entryView==='cards'" @click="entryView='cards'">卡片</button><button :aria-pressed="entryView==='table'" @click="entryView='table'">表格</button></div>
 <div v-if="entryView==='cards'" class="work-row-grid"><article v-for="(row,index) in rows" :key="index" class="work-row-card"><div class="row-between"><h3>工作事项 {{ index+1 }}</h3><el-button v-if="editable" text type="danger" :disabled="busy" @click="rows.splice(index,1);dirty=true">删除</el-button></div><div class="work-fields"><div v-for="f in fields" :key="f.id" class="work-field" :class="{'main-field':f.id==='content'}"><label>{{ f.name }}</label><el-input v-if="editable" v-model="row[f.id]" type="textarea" :rows="f.id==='content'?3:2" maxlength="2000" :aria-label="'第'+(index+1)+'条'+f.name" @input="dirty=true"/><p v-else>{{ row[f.id]||'—' }}</p></div></div></article></div>
 <div v-else class="sheet-scroll" tabindex="0" aria-label="部门填报表格"><table><thead><tr><th>序号</th><th v-for="f in fields" :key="f.id">{{ f.name }}</th><th v-if="editable">操作</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index"><td>{{ index+1 }}</td><td v-for="f in fields" :key="f.id"><el-input v-if="editable" v-model="row[f.id]" type="textarea" :rows="3" maxlength="2000" :aria-label="'第'+(index+1)+'行'+f.name" @input="dirty=true"/><p v-else>{{ row[f.id]||'—' }}</p></td><td v-if="editable"><el-button text type="danger" :disabled="busy" @click="rows.splice(index,1);dirty=true">删除行</el-button></td></tr></tbody></table></div><div v-if="editable" class="collection-actions"><el-button :disabled="rows.length>=100||busy" @click="rows.push(blank());dirty=true">＋ 增加一条</el-button><el-button :loading="busy" @click="save(false)">保存草稿</el-button><el-popconfirm title="提交后即完成，不能再修改。确认提交？" @confirm="save(true)"><template #reference><el-button type="primary" :disabled="busy">提交表格</el-button></template></el-popconfirm></div>
</section>

 <section v-if="detail.canManage" class="panel response-panel"><div class="row-between"><div><h2>已提交内容</h2><p class="muted">选择部门查看已提交的工作事项，未提交草稿仅由该部门查看。</p></div><small class="muted">{{ detail.submitted }} 个部门已提交</small></div><div v-if="!own" class="view-switch" role="group" aria-label="已提交内容展示方式"><button :aria-pressed="submittedView==='cards'" @click="submittedView='cards'">卡片</button><button :aria-pressed="submittedView==='table'" @click="submittedView='table'">表格</button></div><el-collapse v-model="openResponses" class="response-collapse"><el-collapse-item v-for="response in detail.responses" :key="response.id" :name="String(response.id)"><template #title><span class="response-title"><b>{{ response.departmentName }}</b><span>{{ response.status==='SUBMITTED'?'已提交 · '+(response.rows?.length||0)+' 条事项':'待提交' }}</span></span></template><p v-if="response.status!=='SUBMITTED'" class="muted">尚未提交，草稿由部门自行保存。</p><template v-else><div v-if="submittedView==='cards'" class="work-row-grid"><article v-for="(row,index) in response.rows" :key="index" class="work-row-card"><h3>工作事项 {{ index+1 }}</h3><div class="work-fields"><div v-for="f in fields" :key="f.id" class="work-field" :class="{'main-field':f.id==='content'}"><label>{{ f.name }}</label><p>{{ row[f.id]||'—' }}</p></div></div></article></div><div v-else class="sheet-scroll" tabindex="0" :aria-label="response.departmentName+'已提交表格'"><table><thead><tr><th>序号</th><th v-for="f in fields" :key="f.id">{{ f.name }}</th></tr></thead><tbody><tr v-for="(row,index) in response.rows" :key="index"><td>{{ index+1 }}</td><td v-for="f in fields" :key="f.id"><p>{{ row[f.id]||'—' }}</p></td></tr></tbody></table></div></template></el-collapse-item></el-collapse></section>
</template>
</PageState>
</template>

<style scoped>
